struct CMorphingSprite {
    long RenderCount; SListNode* list; STreeNode* header; unsigned long count; int loaded;
    CMorphingSprite() : RenderCount(0), loaded(0)
    {
        list = 0;
        SListNode* node = (SListNode*)std::malloc(sizeof(SListNode));
